import {mergeStates} from './cloud.js';
import {classify,sentences,duration,clamp,escapeHTML as esc,validArticle} from './core.js';
import {sonaController} from './sona-controller.js';
const SONA_VERSION='v0.7.0';
const sonaWordmark=()=>`sona <small class="app-version">${SONA_VERSION}</small>`;
const $=(s)=>document.querySelector(s);const icons={library:'<path d="M4 4h5a3 3 0 0 1 3 2v14a3 3 0 0 0-3-2H4zM20 4h-5a3 3 0 0 0-3 2v14a3 3 0 0 1 3-2h5z"/>',add:'<path d="M12 5v14M5 12h14"/>',queue:'<path d="M4 6h16M4 12h16M4 18h10"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',play:'<path d="m9 5 11 7-11 7z" fill="currentColor" stroke="none"/>',pause:'<path d="M8 5v14M16 5v14" stroke-width="4"/>',back:'<path d="m14 6-6 6 6 6"/>',down:'<path d="m6 9 6 6 6-6"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4z"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 14v6h16v-6"/>',link:'<path d="m10 13 4-4M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m2 1 2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0"/>',moon:'<path d="M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11z"/>',check:'<path d="m5 12 4 4L19 6"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',headphones:'<path d="M4 14v-3a8 8 0 0 1 16 0v3M4 12h4v8H4zM16 12h4v8h-4z"/>',trash:'<path d="M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7"/>',file:'<path d="M5 3h9l5 5v13H5zM14 3v6h5"/>'};const icon=(k,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[k]||icons.file}</svg>`;
const art=(theme,cls='')=>{theme=['technology','care','landscape','growth','connection','discovery'].includes(theme)?theme:'growth';return `<div class="art art-${theme} ${cls}" style="background-image:url('/art/${theme}.svg')" role="img" aria-label="Abstract ${theme} artwork"></div>`};
const examples=[{id:'attention',title:'The art of paying attention',source:'Sona journal',author:'A Sona original',theme:'growth',text:`Attention is a kind of generosity. It is the willingness to be present with what is in front of us: a conversation, a place, a line of thought, without immediately reaching for something else.\n\nWe often think of attention as a tool for getting things done. We measure it in productive hours and completed tasks. But attention also has another life. It is how we notice the world, and how the world becomes meaningful to us.\n\nWhen we slow down, the ordinary begins to reveal itself. A familiar street becomes a place of discovery. The light on a windowsill changes throughout the afternoon. A friend pauses before answering, and in that pause there is something worth hearing.\n\nThere is no special technique. Only the gentle practice of noticing what is already here. Begin with one small thing. The texture of a leaf. The sound of water. The warmth of the cup in your hands. Let it be enough for a moment.\n\nThis does not mean that we must give up our ambitions or withdraw from a busy life. It means that we can return to that life with a little more intention. We can choose what deserves our presence.\n\nThe next time you walk somewhere familiar, leave a small space in your mind for surprise. Look up. Listen. You may find that the world has been waiting patiently for you to notice it.`},{id:'systems',title:'Inside the systems we build',source:'Sona journal',author:'A Sona original',theme:'technology',text:`Every piece of software begins as a way of seeing. Before there is a line of code, there is a question about what matters and how things connect. A calendar is a theory about time. A map is a theory about place. A reading app is a theory about attention.\n\nThe most useful systems are often the ones that know what to leave out. They give us a small number of clear choices. They remember the details so we do not have to. Good technology creates room for a human purpose rather than replacing it.\n\nWhen we build a tool, we also build a habit. The shape of a button, the rhythm of a notification, the decision to save our place: each one gently influences what happens next. Those decisions deserve care.\n\nA quiet interface can still be expressive. A simple system can still be powerful. The challenge is to let complexity exist beneath the surface while keeping the experience above it generous and understandable.\n\nPerhaps the best measure of a tool is not how much time we spend with it, but how well it helps us return to the things we wanted to do in the first place.`},{id:'kindness',title:'A small act of kindness',source:'Sona journal',author:'A Sona original',theme:'care',text:`Help does not always arrive as a grand gesture. Sometimes it is someone remembering how you take your coffee. Sometimes it is a message that asks nothing in return. Sometimes it is a hand offered before you know how to ask.\n\nSmall acts of care matter because they make another person's day less solitary. They say: I noticed. You are not carrying this alone.\n\nKindness is not the same as having all the answers. Often the most useful thing we can do is listen without trying to repair everything. To stay present. To offer a specific, ordinary kind of support.\n\nBring a meal. Make the call. Walk alongside someone for a while. The scale of the gesture matters less than the attention behind it.\n\nA generous life is built from these small repetitions. We practice care until it becomes a way of moving through the world.`},{id:'ridge',title:'Beyond the ridge',source:'Sona journal',author:'A Sona original',theme:'landscape',text:`From below, the mountain looks like a single shape. But as you climb, the shape becomes a collection of details: a seam of pale rock, a patch of grass sheltered from the wind, water finding its way through a crack.\n\nThe path asks for a different kind of patience. You cannot hurry the distance away. You can only take the next step, and then the next.\n\nAt the ridge the landscape opens. What seemed like an ending becomes a place to see farther. There are other valleys, other paths, other ways down.\n\nThe mountain offers no instruction beyond this: keep paying attention. The world is larger than the view you started with.`},{id:'questions',title:'Why we ask better questions',source:'Sona journal',author:'A Sona original',theme:'discovery',text:`A good question changes the room. It interrupts the easy answer and makes space for something less familiar. What are we missing? What would change our minds? What else could be true?\n\nCuriosity is not a performance of cleverness. It is a willingness to remain a beginner for a little longer. To let the evidence surprise us. To admit that another person may see something we do not.\n\nThe best questions are often simple. They are asked with genuine interest, and followed by genuine listening. They open a conversation rather than close an argument.\n\nWe learn more when we stop trying to win the next sentence. Ask one more question. Give the answer time to arrive.`}];
let state={articles:examples.map(a=>({...a,position:0,bookmarks:[],added:Date.now()})),queue:[],currentId:'attention',rate:1,voiceURI:'',autoplay:true};try{const saved=JSON.parse(localStorage.getItem('sona.v1'));if(saved&&Array.isArray(saved.articles)){state={...state,...saved,articles:saved.articles.filter(validArticle).map(a=>({...a,bookmarks:a.bookmarks||[],position:a.position||0}))}}}catch{}
let cloudRevision=null,cloudReady=false,cloudSaving=false,cloudDirty=false,syncTimer,cloudStatus='Connecting to cloud…',hasLocal=false;try{hasLocal=!!localStorage.getItem('sona.v1')}catch{}let providerInfo={connected:false,google:false,azure:false},premiumVoices=[],premiumModels=[],freeVoices={google:[],azure:[]},audioLoading=false;let audio=typeof Audio!=='undefined'?new Audio():null;let audioAbort=null;state.audioEngine=state.audioEngine||'google';const fingerprints=new Map(state.articles.map(a=>[a.id,JSON.stringify(a)]));state.deleted=state.deleted||{};
let view='library',query='',voiceQuery='',filter='all',playing=false,readMode=false,voices=[],speechToken=0,timer=null,timerUntil=0,importMode='url',preview=null,busy=false,importError='',voiceBusy=false,voiceError='';let storageWarning=false;
function persist(){stampChanges();cloudDirty=true;if(cloudReady){clearTimeout(syncTimer);syncTimer=setTimeout(()=>flushCloud(),700)}try{localStorage.setItem('sona.v1',JSON.stringify(state))}catch{if(!storageWarning){toast('Storage is full. Export your library to keep a backup.');storageWarning=true}}sonaController.publish(publicSnapshot());}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
const current=()=>state.articles.find(a=>a.id===state.currentId);const btn=(label,act,cls='button',extra='')=>`<button class="${cls}" data-action="${act}" ${extra}>${label}</button>`;const ib=(k,act,label,extra='')=>btn(icon(k),act,'icon-button',`aria-label="${label}" ${extra}`);
function progress(a){return Math.round(clamp((a?.position||0)/Math.max(1,sentences(a?.text||'').length),0,1)*100)}
function articleRow(a,queue=false){return `<div class="article-row">${btn(art(a.theme),'open','art-button',`data-id="${a.id}" aria-label="Open ${esc(a.title)}"`)}<button class="row-copy" data-action="open" data-id="${a.id}"><span>${esc(a.title)}</span><small>${esc(a.source||'Your library')} · ${duration(a.text)} min${a.finished?' · Finished':''}</small></button>${queue?`${ib('play','play-id','Play article',`data-id="${a.id}"`)}${ib('close','dequeue','Remove from queue',`data-id="${a.id}"`)}`:ib('more','actions','Article actions',`data-id="${a.id}"`)}</div>`}
function nav(){return `<nav class="nav" aria-label="Main navigation">${[['library','Library'],['add','Add'],['queue','Queue'],['voices','Voices']].map(([key,label])=>btn(icon(key)+`<span>${label}</span>`,key,'nav-link '+(view===key?'selected':''))).join('')}</nav>`}
function mini(){const a=current();if(!a||view==='player')return '';return `<div class="mini"><button class="mini-open" data-action="player">${art(a.theme)}<span>${esc(a.title)}<small>${playing?'Listening now':progress(a)+'% read'} · ${esc(voiceName())}</small></span></button>${ib(playing?'pause':'play','toggle',playing?'Pause':'Play')}${ib('queue','queue','Open queue')}</div>`}
function publicVoiceSnapshot(){const provider=state.audioEngine||'google',source=provider==='google'?freeVoices.google:provider==='azure'?freeVoices.azure:provider==='eleven'?premiumVoices:voices.map(v=>({id:v.voiceURI,name:v.name,language:v.lang,description:v.localService?'On device':'Online voice'})),selectedVoiceId=provider==='device'?state.voiceURI:state[provider+'Voice']||(provider==='eleven'?state.elevenVoice:'');return {provider,providers:{google:{isConnected:!!providerInfo.google,isViaLire:!!providerInfo.googleViaLire,status:providerInfo.google?'connected':'unavailable'},azure:{isConnected:!!providerInfo.azure,isViaLire:!!providerInfo.azureViaLire,status:providerInfo.azure?'connected':'disconnected'},eleven:{isConnected:!!providerInfo.connected,isViaLire:false,status:providerInfo.connected?'connected':'disconnected'},device:{isConnected:true,isViaLire:false,status:'available'}},voices:source.map(v=>({id:v.id,name:v.name,language:v.language||'',description:v.description||[v.labels?.accent,v.labels?.gender].filter(Boolean).join(' · ')})),selectedVoiceId,isLoading:voiceBusy,error:voiceError};}
function publicSnapshot(){const active=current(),parts=sentences(active?.text||''),articles=state.articles.map(a=>({id:a.id,title:a.title,source:a.source||'',author:a.author||'',url:a.url||'',theme:a.theme||'growth',position:a.position||0,finished:!!a.finished,progress:progress(a),duration:duration(a.text)})),byId=new Map(articles.map(a=>[a.id,a]));return {view,query,filter,importMode,busy,importError,timerUntil,autoplay:!!state.autoplay,voice:publicVoiceSnapshot(),preview:preview?{title:preview.title,source:preview.source||'Your library',duration:duration(preview.text),excerpt:preview.text.slice(0,190)+'…'}:null,currentId:state.currentId,currentArticle:active?{id:active.id,title:active.title,source:active.source||'',author:active.author||'',theme:active.theme||'growth',position:active.position||0,sentenceCount:parts.length,activeSentence:parts[active.position||0]||'',duration:duration(active.text),isBookmarked:(active.bookmarks||[]).includes(active.position||0)}:null,articles,queue:[...state.queue],queueArticles:state.queue.map(id=>byId.get(id)).filter(Boolean),playback:{playing,rate:state.rate,engine:state.audioEngine,readMode},cloudStatus};}
function navigate(viewName){if(!['library','add','queue','voices','player'].includes(viewName)||(viewName==='player'&&!current()))return false;view=viewName;render();window.scrollTo?.(0,0);return true}
async function prepareImport(command){if(busy)return false;busy=true;importError='';preview=null;sonaController.publish(publicSnapshot());try{let data;if(command.mode==='url'){const r=await fetch('/api/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url:String(command.url||'')})});data=await r.json();if(!r.ok)throw new Error(data.error||'Could not load article.')}else if(command.mode==='text'){const text=String(command.text||'').trim(),title=String(command.title||'').trim();if(!text)throw new Error('Add some text first.');data={title,text,source:'Your words',author:''}}else if(command.mode==='file'){const file=Array.isArray(command.file)?command.file[0]:command.file;if(!file)throw new Error('Choose a file first.');if(file.size>15*1024*1024)throw new Error('Please choose a file smaller than 15 MB.');let words;if(/\.pdf$/i.test(file.name)){const pdfjs=await import('https://cdn.jsdelivr.net/npm/pdfjs-dist@5.4.394/build/pdf.mjs');pdfjs.GlobalWorkerOptions.workerSrc='https://cdn.jsdelivr.net/npm/pdfjs-dist@5.4.394/build/pdf.worker.mjs';const pdf=await pdfjs.getDocument({data:await file.arrayBuffer()}).promise,pages=[];for(let i=1;i<=pdf.numPages;i++){const page=await pdf.getPage(i),content=await page.getTextContent();pages.push(content.items.map(x=>x.str).join(' '))}words=pages.join('\n\n');if(words.trim().length<30)throw new Error('This PDF may be a scanned image. Copy its text with OCR and use Paste text.')}else if(/\.html?$/i.test(file.name)){const doc=new DOMParser().parseFromString(await file.text(),'text/html');doc.querySelectorAll('script,style,nav,footer,header').forEach(n=>n.remove());words=(doc.querySelector('article,main')||doc.body).textContent}else words=await file.text();data={title:file.name.replace(/\.[^.]+$/,''),text:words.trim(),source:'Your files',author:''}}else return false;if(!validArticle(data))throw new Error('No readable text was found.');if(data.text.length>150000)throw new Error('This article is too long. Please split it into smaller sections.');preview={...data,theme:classify(data.title+' '+data.text)};return true}catch(error){importError=error.message||'Could not prepare this reading.';return false}finally{busy=false;sonaController.publish(publicSnapshot())}}
async function refreshVoiceProvider(){const provider=state.audioEngine;voiceBusy=true;voiceError='';sonaController.publish(publicSnapshot());try{if(provider==='device')loadVoices();else if(provider==='eleven')await loadPremiumVoices();else{const r=await fetch('/api/tts/status'),data=await r.json();if(r.ok)providerInfo={...providerInfo,...data};if(providerInfo[provider])await loadFreeVoices(provider)}return true}catch(error){voiceError=error.message||'Could not load voices.';throw error}finally{voiceBusy=false;sonaController.publish(publicSnapshot())}}
async function connectVoiceProvider(command){const provider=command.provider;if(provider==='google')return refreshVoiceProvider();if(!['azure','eleven'].includes(provider))return false;voiceBusy=true;voiceError='';sonaController.publish(publicSnapshot());try{const endpoint=provider==='eleven'?'/api/eleven/connect':'/api/tts/connect',body=provider==='eleven'?{key:command.key}:{provider,key:command.key,region:command.region},r=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),data=await r.json();if(!r.ok)throw new Error(data.error||'Could not connect provider.');if(provider==='eleven'){providerInfo.connected=true;await loadPremiumVoices()}else{providerInfo.azure=true;providerInfo.azureViaLire=true;await loadFreeVoices('azure')}state.audioEngine=provider;persist();return true}catch(error){voiceError=error.message||'Could not connect provider.';throw error}finally{voiceBusy=false;sonaController.publish(publicSnapshot())}}
async function disconnectVoiceProvider(provider){if(!['azure','eleven'].includes(provider))return false;const endpoint=provider==='eleven'?'/api/eleven/connect':'/api/tts/connect?provider='+provider,r=await fetch(endpoint,{method:'DELETE'});if(!r.ok)throw new Error('Could not disconnect provider.');stopSpeech();if(provider==='eleven'){providerInfo.connected=false;premiumVoices=[]}else{providerInfo.azure=false;freeVoices.azure=[]}state.audioEngine=providerInfo.google?'google':'device';persist();render();return true}
sonaController.connect({dispatch(command){switch(command.type){case'navigate':return navigate(command.view);case'set-query':query=String(command.query||'');render();return true;case'set-filter':if(!['all','unread','finished'].includes(command.filter))return false;filter=command.filter;render();return true;case'open-article':if(!state.articles.some(a=>a.id===command.id))return false;open(command.id,!!command.play);return true;case'article-action':{const names={enqueue:'enqueue','toggle-finished':'finished',download:'download',remove:'delete-confirm'},name=names[command.action];if(!name||!state.articles.some(a=>a.id===command.id))return false;action(name,{dataset:{id:command.id}});return true}case'set-import-mode':if(!['url','text','file'].includes(command.mode))return false;importMode=command.mode;preview=null;importError='';render();return true;case'submit-import':return prepareImport(command);case'save-preview':if(!preview)return false;{const item={...preview,id:crypto.randomUUID(),position:0,bookmarks:[],added:Date.now()};state.articles.unshift(item);persist();preview=null;if(command.play)open(item.id,true);else{view='library';render();toast('Saved to your library.')}return true}case'toggle-playback':toggle();return true;case'seek':seekTo(Number(command.position));return true;case'skip':action(command.direction<0?'rewind':'forward',{dataset:{}});return true;case'set-read-mode':readMode=!!command.readMode;render();return true;case'bookmark':action('bookmark',{dataset:{}});return true;case'cycle-rate':{const rates=[.75,1,1.25,1.5,1.75,2],index=rates.indexOf(state.rate),next=rates[(index+1)%rates.length];action('set-speed',{dataset:{rate:String(next)}});return true}case'cycle-timer':{const remaining=Math.max(0,Math.ceil((timerUntil-Date.now())/60000)),next=remaining===0?15:remaining<=15?30:remaining<=30?60:0;action('set-timer',{dataset:{minutes:String(next)}});return true}case'queue-remove':action('dequeue',{dataset:{id:command.id}});return true;case'queue-move-up':action('move-up',{dataset:{id:command.id}});return true;case'set-autoplay':state.autoplay=!!command.value;persist();render();return true;case'voice-select-provider':if(!['google','azure','eleven','device'].includes(command.provider))return false;stopSpeech();state.audioEngine=command.provider;persist();return refreshVoiceProvider();case'voice-select':{const provider=state.audioEngine,list=provider==='google'?freeVoices.google:provider==='azure'?freeVoices.azure:provider==='eleven'?premiumVoices:voices.map(v=>({id:v.voiceURI}));if(!list.some(v=>v.id===command.voiceId))return false;if(provider==='device')state.voiceURI=command.voiceId;else state[provider+'Voice']=command.voiceId;persist();return true}case'voice-refresh':return refreshVoiceProvider();case'voice-connect':return connectVoiceProvider(command);case'voice-disconnect':return disconnectVoiceProvider(command.provider);default:return false}}});
function render(){const a=current();$('#app').innerHTML=`<section class="main view-${view}"><header class="topbar"><span class="top-note">A QUIETER KIND OF LISTENING</span>${ib('more','mobile-tools','Cloud and audio tools')}</header><section class="content">${view==='library'?library():view==='add'?add():view==='queue'?queue():view==='voices'?voicesPage():view==='player'&&a?player(a):library()}</section><footer class="playback-dock">${mini()}</footer></section>`;bind();updatePlayback();sonaController.publish(publicSnapshot());}
function library(){const items=state.articles.filter(a=>(filter!=='finished'||a.finished)&&(filter!=='unread'||!a.finished)&&(a.title+' '+a.source).toLowerCase().includes(query.toLowerCase()));const a=current();return `<div class="eyebrow">YOUR OWN LITTLE CORNER</div><div class="page-heading"><h1>Something worth<br>your time.</h1><p>Your words. Your pace.<br>A little room to take it all in.</p></div><label class="search">${icon('search')}<input id="search" placeholder="Search your articles" value="${esc(query)}" aria-label="Search articles">${query?ib('close','clear-search','Clear search'):''}</label><div class="filters">${[['all','All articles'],['unread','To listen'],['finished','Finished']].map(([k,l])=>btn(l,'filter','chip '+(filter===k?'on':''),`data-filter="${k}"`)).join('')}<span>${items.length} articles</span></div>${!query&&a&&filter!=='finished'?`<button class="hero" data-action="player">${art(a.theme)}<div class="hero-shade"></div><div class="hero-copy"><span class="eyebrow">${a.finished?'LISTEN AGAIN':'PICK UP WHERE YOU LEFT OFF'}</span><h2>${esc(a.title)}</h2><span>${esc(a.source)} · ${duration(a.text)} min listen</span><div class="hero-bottom"><div><div class="track"><i style="width:${progress(a)}%"></i></div><small>${progress(a)}% read · ${a.finished?'Finished':'Your place is saved'}</small></div><span class="round-play">${icon(playing?'pause':'play')}</span></div></div></button>`:''}<div class="section-heading"><h2>${query?'Search results':'Saved for a good moment'}</h2>${btn(icon('add')+' Add article','add','text-button')}</div><div class="article-list">${items.length?items.map(x=>articleRow(x)).join(''):`<div class="empty">${icon(query?'search':'library')}<h2>${query?'Nothing here just yet.':'Your library starts here.'}</h2><p>${query?'Try another title or source.':'Paste a link or bring your own words.'}</p>${btn(query?'Clear search':'Add your first article',query?'clear-search':'add')}</div>`}</div><div class="library-note">Five short Sona originals are included to try the player. Add your own reading whenever you’re ready.</div>`}
function add(){return `<div class="eyebrow">BRING YOUR OWN READING</div><h1>Bring something<br>good.</h1><p class="lede">A link, a document, a few words of your own.<br>We’ll give them room to be heard.</p><div class="import-tabs">${[['url','link','Paste a link'],['text','file','Paste text'],['file','upload','Upload file']].map(([k,i,l])=>btn(icon(i)+l,'import-mode','import-tab '+(importMode===k?'on':''),`data-mode="${k}"`)).join('')}</div><form id="import-form" class="import-form">${importMode==='url'?`<label class="field-label" for="article-url">ARTICLE LINK</label><input class="input" id="article-url" type="url" placeholder="https://a-story-worth-reading.com/article" required><p class="field-help">Public articles work best. If a page blocks readers, paste its text instead.</p>`:importMode==='text'?`<label class="field-label" for="article-title">TITLE</label><input class="input" id="article-title" placeholder="Something worth remembering" required maxlength="250"><label class="field-label" for="article-text">YOUR WORDS</label><textarea id="article-text" class="input" rows="9" placeholder="Start writing or paste an article here…" required></textarea>`:`<label class="file-drop" for="article-file">${icon('upload')}<strong>Drop a little reading here.</strong><span>or choose a file</span><small>PDF, TXT, Markdown, HTML · up to 15 MB</small><input id="article-file" type="file" accept=".txt,.md,.markdown,.html,.htm,.pdf" required></label>`}<button class="button" type="submit" ${busy?'disabled':''}>${busy?'<span class="spinner"></span> Preparing your reading…':importMode==='url'?'Find article '+icon('arrow'):'Prepare article '+icon('arrow')}</button><p id="import-error" class="error" role="alert"></p></form>${preview?`<div class="preview-card">${art(preview.theme)}<div><span class="eyebrow">READY WHEN YOU ARE</span><h2>${esc(preview.title)}</h2><p>${esc(preview.source)} · ${duration(preview.text)} min listen</p><p class="preview-excerpt">${esc(preview.text.slice(0,190))}…</p><div class="preview-buttons">${btn('Save & listen','save-play')}${btn('Save to library','save-only','secondary-button')}</div></div></div>`:''}<div class="privacy-note">${icon('library')} Your library syncs privately across your devices. A local backup keeps your reading safe while offline.</div>`}
function queue(){const a=current(),items=state.queue.map(id=>state.articles.find(a=>a.id===id)).filter(Boolean);return `<div class="eyebrow">ONE GOOD READ AFTER ANOTHER</div><h1>A little more<br>to listen to.</h1><p class="lede">Make a little space. We’ll keep your place.</p>${a?`<div class="queue-current"><span class="eyebrow">NOW ${playing?'PLAYING':'READY'}</span>${articleRow(a)}<div class="track"><i style="width:${progress(a)}%"></i></div></div>`:''}<div class="section-heading"><h2>Up next <span class="muted">(${items.length})</span></h2><span>${items.reduce((n,a)=>n+duration(a.text),0)} min</span></div><div class="article-list">${items.length?items.map((x,i)=>`<div class="queued"><span class="queue-order">${i+1}</span>${articleRow(x,true)}${i?btn('↑','move-up','small-button',`data-id="${x.id}" aria-label="Move up"`):''}</div>`).join(''):`<div class="empty">${icon('queue')}<h2>Room for one more.</h2><p>Add articles from the ··· menu in your library.</p>${btn('Browse your library','library','secondary-button')}</div>`}</div><label class="toggle-row"><span><strong>Keep the stories coming</strong><small>Automatically play the next article</small></span><input type="checkbox" id="autoplay" ${state.autoplay?'checked':''}><span class="switch"></span></label>`}
function voicesPage(){const provider=state.audioEngine||'google',providerNames={google:'Google Chirp 3 HD',azure:'Azure Neural',eleven:'ElevenLabs',device:'Device voices'},source=provider==='google'?freeVoices.google:provider==='azure'?freeVoices.azure:provider==='eleven'?premiumVoices:voices.map(v=>({id:v.voiceURI,name:v.name,language:v.lang,description:v.localService?'On device':'Online voice'})),needle=voiceQuery.toLowerCase(),list=source.filter(v=>(v.name+' '+(v.language||'')+' '+(v.description||'')).toLowerCase().includes(needle)),selected=provider==='device'?state.voiceURI:state[provider+'Voice']||(provider==='eleven'?state.elevenVoice:''),connected=provider==='device'||providerInfo[provider==='eleven'?'connected':provider],quota=provider==='google'&&providerInfo.googleViaLire?`Connected through Lire · ${Number(providerInfo.googleMonthlyCharacterLimit||800000).toLocaleString()} shared characters each month`:provider==='azure'&&providerInfo.azureViaLire?`Connected through Lire · ${Number(providerInfo.azureMonthlyCharacterLimit||500000).toLocaleString()} free characters each month`:provider==='azure'?'Azure Neural · 500,000 free characters each month':provider==='eleven'?'ElevenLabs · 10,000 free credits each month':'Device narration';return `<div class="voices-page"><div class="eyebrow">YOUR LISTENING VOICES</div><h1>Voices</h1><p class="voice-page-intro">Find the voice that makes you want to stay with the story.</p><div class="voice-provider-tabs">${[['google','Google'],['azure','Azure'],['eleven','ElevenLabs'],['device','On device']].map(([id,label])=>btn(label,'select-provider','voice-provider '+(provider===id?'active':''),`data-provider="${id}"`)).join('')}</div><div class="voice-provider-note"><span><strong>${providerNames[provider]}</strong><small>${quota}</small></span>${(provider==='google'||provider==='azure')&&connected&&providerInfo[provider+'ViaLire']?'<span class="provider-status"><i></i>Connected in Lire</span>':connected?'<span class="provider-status"><i></i>Connected</span>':''}</div>${provider!=='device'?`<label class="voice-search"><span>⌕</span><input id="voice-search" value="${esc(voiceQuery)}" placeholder="Search voices" aria-label="Search voices"></label>`:''}${connected?`<div class="voice-catalog">${list.length?list.map((v,i)=>{const chosen=v.id===selected,detail=provider==='google'?`${v.language==='en-US'?'English · United States':'French · France'}${v.gender?' · '+v.gender.toLowerCase():''}`:provider==='azure'?`${v.language||'Neural'}${v.gender?' · '+v.gender:''}`:provider==='eleven'?([v.labels?.accent,v.labels?.gender,v.labels?.description].filter(Boolean).join(' · ')||v.description?.slice(0,90)||'ElevenLabs voice'):`${v.language||'Device voice'} · ${v.localService?'On device':'Online voice'}`;return `<button class="voice-catalog-row" data-action="select-catalog-voice" data-provider="${provider}" data-voice="${esc(v.id)}"><span class="voice-orb orb orb-${i%4}"></span><span class="voice-copy"><strong>${esc(v.name)}</strong><small>${esc(detail)}</small></span>${chosen?icon('check','voice-check'):''}</button>`}).join(''):`<div class="empty voice-empty"><h2>${source.length?'No voices match your search.':'No voices available yet.'}</h2><p>${source.length?'Try another name or language.':'Refresh the voice list or check the provider connection.'}</p>${btn('Refresh voices','refresh-provider','secondary-button')}</div>`}</div>`:`<div class="voice-connect-panel"><h2>Connect ${providerNames[provider]}</h2><p>${provider==='google'?'Sona can use the Google Chirp connection already configured in Lire.':provider==='azure'?'Connect an Azure Speech F0 resource once; Sona will securely reuse the Lire connection.':'Connect an ElevenLabs key to use its free monthly credits.'}</p>${btn(provider==='google'?'Check Lire connection':provider==='azure'?'Connect Azure in Lire':'Set up '+providerNames[provider],provider==='azure'?'connect-azure':'select-provider','button',`data-provider="${provider}"`)}${provider==='google'?'<p class="field-help">Google Chirp 3 HD is already set up in Lire. Sona reuses that secure connection.</p>':provider==='azure'?'<p class="field-help">Your key is validated and stored in Lire, then shared securely with Sona.</p>':''}</div>`}<p class="voice-page-footnote">Tap a voice to select it. Generated audio is cached so replaying the same passage does not use more provider quota.</p></div>`}
function player(a){const ss=sentences(a.text);return `<div class="player-header">${ib('down','library','Back to library')}<span class="eyebrow">${playing?'NOW PLAYING':'YOUR LISTENING SPACE'}</span>${ib('more','actions','Article actions',`data-id="${a.id}"`)}</div><div class="player-layout"><div class="player-art-column">${art(a.theme,'player-art')}<span class="art-caption">A FLEETING IMPRESSION · ${esc(a.theme.toUpperCase())}</span><h1>${esc(a.title)}</h1><p class="byline">${esc(a.author||a.source)}${a.author?' · '+esc(a.source):''}</p></div><div class="player-controls-column"><div class="read-toggle">${btn(icon('headphones')+' Listen','listen-mode',!readMode?'on':'')}${btn(icon('library')+' Read along','read-mode',readMode?'on':'')}</div>${readMode?`<div class="reader" tabindex="0" aria-label="Article text">${ss.map((s,i)=>`<button class="sentence ${i===(a.position||0)?'spoken':''}" data-action="jump" data-index="${i}">${esc(s)} </button>`).join('')}</div>`:`<div class="passage"><span class="eyebrow">READING NOW</span><p id="spoken-passage">${esc(ss[a.position||0]||ss[0])}</p></div>`}<div class="seek"><label class="sr-only" for="seek">Reading position</label><input id="seek" type="range" min="0" max="${Math.max(0,ss.length-1)}" value="${a.position||0}"><div class="time-row"><span id="elapsed">${formatTime(estimatedSeconds(a)*(progress(a)/100))}</span><span>${formatTime(estimatedSeconds(a))}</span></div></div><div class="transport">${btn('<span>↶</span><small>15</small>','rewind','skip-button','aria-label="Back approximately 15 seconds"')}${btn(icon(playing?'pause':'play'),'toggle','main-play',`aria-label="${playing?'Pause':'Play'}"`)}${btn('<span>↷</span><small>15</small>','forward','skip-button','aria-label="Forward approximately 15 seconds"')}</div><div class="play-tools">${btn(state.rate+'×','speed','chip')}${btn('<span class="orb"></span> '+esc(voiceName())+' '+icon('down'),'voices','chip voice-chip')}${btn(icon('moon')+' '+(timerUntil?'Timer on':'Timer'),'timer','chip')}</div><div class="player-bottom">${btn(icon('bookmark')+' Bookmark','bookmark','text-button')}${btn(icon('queue')+' Up next','queue','text-button')}</div>${a.bookmarks.length?btn(a.bookmarks.length+' saved passages','bookmarks','text-button bookmark-count'):''}<p class="voice-note">${['eleven','google','azure'].includes(state.audioEngine)?(state.audioEngine==='google'?'Google Chirp 3 HD · generated audio is cached.':state.audioEngine==='azure'?'Azure Neural · generated audio is cached.':providerInfo.connected?'ElevenLabs streaming · generated audio is cached.':'Choose a voice provider.'):(voices.length?'Device narration.':'Waiting for device voices…')} Keep this page open while listening.</p></div></div>`}
const estimatedSeconds=a=>a.text.trim().split(/\s+/).length/(155*state.rate)*60;const formatTime=s=>`${Math.floor(s/60)}:${String(Math.floor(s%60)).padStart(2,'0')}`;
function voiceName(){if(state.audioEngine==='eleven')return premiumVoices.find(v=>v.id===state.elevenVoice)?.name||(providerInfo.connected?'ElevenLabs':'Choose a voice');if(state.audioEngine==='google'||state.audioEngine==='azure'){const list=freeVoices[state.audioEngine]||[];return list.find(v=>v.id===state[state.audioEngine+'Voice'])?.name||({google:'Google Chirp 3 HD',azure:'Azure Neural'}[state.audioEngine])}const v=voices.find(v=>v.voiceURI===state.voiceURI);return v?v.name.replace(/Microsoft |Google |Apple /g,'').split(' - ')[0]:'Device voice'}
function stopSpeech(){speechToken++;window.speechSynthesis?.cancel();if(audio){audio.pause();audio.removeAttribute?.('src');audio.load?.()}audioAbort?.abort();audioAbort=null;audioLoading=false;playing=false}
function speakFrom(index){if(['eleven','google','azure'].includes(state.audioEngine)){if(state.audioEngine==='eleven'&&!providerInfo.connected){connectModal();return}if(state.audioEngine==='google'&&!providerInfo.google){view='voices';render();toast('Google Chirp is not ready in Lire. Open Lire and check its Google voice connection.');return}if(state.audioEngine==='azure'&&!providerInfo.azure){freeConnectModal('azure');return}return speakPremium(index)}const a=current();if(!a)return;if(!('speechSynthesis'in window)){toast('Read-aloud is not supported in this browser. Try Chrome, Edge or Safari.');return}stopSpeech();const ss=sentences(a.text);a.position=clamp(index,0,ss.length-1);a.finished=false;playing=true;const token=speechToken;render();const run=()=>{if(token!==speechToken||!playing)return;const phrase=ss[a.position];if(!phrase){finishArticle();return}const u=new SpeechSynthesisUtterance(phrase);u.rate=state.rate;const selected=voices.find(v=>v.voiceURI===state.voiceURI);if(selected){u.voice=selected;u.lang=selected.lang}u.onend=()=>{if(token!==speechToken)return;a.position++;persist();if(a.position>=ss.length){finishArticle();return}updatePlayback();run()};u.onerror=e=>{if(token!==speechToken||['interrupted','canceled'].includes(e.error))return;playing=false;render();toast('The voice could not play. Choose another device voice and try again.')};window.speechSynthesis.speak(u)};run();persist();}
function finishArticle(){const a=current();if(a){a.finished=true;a.position=0}stopSpeech();persist();if(state.autoplay&&state.queue.length){const next=state.queue.shift();state.currentId=next;persist();speakFrom(0)}else{render();toast('Finished. A little more room for your next story.')}}
function updatePlayback(){const a=current();if(!a)return;const ss=sentences(a.text);if($('#spoken-passage'))$('#spoken-passage').textContent=ss[a.position||0]||ss[0];if($('#seek'))$('#seek').value=a.position||0;if($('#elapsed'))$('#elapsed').textContent=formatTime(estimatedSeconds(a)*(progress(a)/100));document.querySelectorAll('.sentence').forEach((n,i)=>n.classList.toggle('spoken',i===(a.position||0)));const n=$('.sentence.spoken');if(n&&readMode)n.scrollIntoView({block:'nearest',behavior:'smooth'});}
function toggle(){if(playing){stopSpeech();persist();render()}else speakFrom(current()?.position||0)}
function open(id,play=false){if(state.currentId!==id)stopSpeech();state.currentId=id;view='player';state.queue=state.queue.filter(x=>x!==id);persist();if(play)speakFrom(current()?.position||0);else render();window.scrollTo(0,0)}
function modal(title,content){$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-header"><h2>${title}</h2>${ib('close','close-modal','Close')}</div>${content}</section></div>`;$('#modal-root').querySelector('[data-action="close-modal"]').focus();$('#modal-root').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))closeModal();const b=e.target.closest('[data-action]');if(b)action(b.dataset.action,b)};$('#modal-root').onchange=()=>{};}
function closeModal(){$('#modal-root').innerHTML=''}
function deviceVoiceModal(){modal('Find your voice.',`<p class="modal-intro">Real voices available on your device. Choose one for your next listen.</p>${voices.length?`<div class="voice-list">${voices.map((v,i)=>`<button class="voice-option ${v.voiceURI===state.voiceURI?'chosen':''}" data-action="choose-voice" data-index="${i}"><span class="orb orb-${i%3}"></span><span><strong>${esc(v.name)}</strong><small>${esc(v.lang)} · ${v.localService?'On device':'Online voice'}</small></span>${v.voiceURI===state.voiceURI?icon('check'):icon('play')}</button>`).join('')}</div>`:'<p>No voices are available yet. Try your browser’s speech settings or reload this page.</p>'}`)}
function action(name,b){const a=current();switch(name){case'select-provider':selectProvider(b.dataset.provider);break;case'connect-azure':freeConnectModal('azure');break;case'refresh-provider':loadFreeVoices(state.audioEngine).then(()=>{render();toast('Voice list updated.')}).catch(e=>toast(e.message));break;case'select-catalog-voice':{const provider=b.dataset.provider,was=playing;stopSpeech();state.audioEngine=provider;if(provider==='device')state.voiceURI=b.dataset.voice;else state[provider+'Voice']=b.dataset.voice;persist();render();if(was)speakFrom(a?.position||0);break}case'choose-free-voice':{const provider=b.dataset.provider,was=playing;stopSpeech();state.audioEngine=provider;state[provider+'Voice']=b.dataset.voice;persist();closeModal();if(was)speakPremium(a?.position||0);else render();break}case'disconnect-free':{const provider=b.dataset.provider;fetch('/api/tts/connect?provider='+provider,{method:'DELETE'}).then(r=>{if(!r.ok)throw new Error();providerInfo[provider]=false;freeVoices[provider]=[];state.audioEngine='google';persist();closeModal();render();toast((provider==='google'?'Google':'Azure')+' disconnected.')}).catch(()=>toast('Could not disconnect provider.'));break}case'connect-eleven':connectModal();break;case'use-premium':state.audioEngine='eleven';persist();voiceModal();break;case'use-device':stopSpeech();state.audioEngine='device';persist();deviceVoiceModal();render();break;case'choose-premium':{const was=playing;stopSpeech();state.audioEngine='eleven';state.elevenVoice=b.dataset.voice;persist();closeModal();if(was)speakPremium(a?.position||0);else render();break}case'disconnect-eleven':{disconnectEleven();break}case'cloud-sync':flushCloud(true);break;case'mobile-tools':modal('Your listening space.',`<p class="modal-intro">${esc(cloudStatus)}. Your library travels with you.</p>${btn('Sync now','cloud-sync','option-row')}${btn('Choose a voice','voices','option-row')}${btn('Export library backup','export','option-row')}`);break;case'library':case'add':case'queue':case'player':view=name;render();window.scrollTo(0,0);break;case'open':open(b.dataset.id);break;case'play-id':open(b.dataset.id,true);break;case'toggle':toggle();break;case'clear-search':query='';render();break;case'filter':filter=b.dataset.filter;render();break;case'import-mode':importMode=b.dataset.mode;preview=null;render();break;case'save-play':case'save-only':if(preview){const item={...preview,id:crypto.randomUUID(),position:0,bookmarks:[],added:Date.now()};state.articles.unshift(item);persist();preview=null;if(name==='save-play')open(item.id,true);else{view='library';render();toast('Saved to your library.')}}break;case'read-mode':readMode=true;render();break;case'listen-mode':readMode=false;render();break;case'jump':seekTo(Number(b.dataset.index));break;case'rewind':case'forward':{if(!a)break;const ss=sentences(a.text),avg=a.text.split(/\s+/).length/ss.length,steps=Math.max(1,Math.round(15/(avg/(155*state.rate)*60)));seekTo((a.position||0)+(name==='forward'?steps:-steps));break}case'voices':voiceModal();break;case'choose-voice':{state.voiceURI=voices[Number(b.dataset.index)]?.voiceURI||'';persist();const was=playing;closeModal();if(was)speakFrom(a.position||0);else render();toast('Voice selected: '+voiceName());break}case'speed':modal('Find your rhythm.',`<p class="modal-intro">Playback speed</p><div class="speed-grid">${[.75,1,1.25,1.5,1.75,2].map(n=>btn(n+'×','set-speed','chip '+(state.rate===n?'on':''),`data-rate="${n}"`)).join('')}</div>`);break;case'set-speed':state.rate=Number(b.dataset.rate);persist();closeModal();if(playing&&['eleven','google','azure'].includes(state.audioEngine)){audio.playbackRate=state.rate;render()}else if(playing)speakFrom(a.position||0);else render();break;case'timer':modal('Drift off at your pace.',`<p class="modal-intro">Audio stops when the sleep timer ends.</p><div class="timer-list">${[0,15,30,45,60].map(n=>btn(n?n+' minutes':'Off','set-timer','option-row',`data-minutes="${n}"`)).join('')}</div>${timerUntil?'<p class="modal-intro">Timer ends at '+new Date(timerUntil).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})+'</p>':''}`);break;case'set-timer':clearTimeout(timer);timerUntil=0;{const min=Number(b.dataset.minutes);if(min){timerUntil=Date.now()+min*60000;timer=setTimeout(()=>{stopSpeech();timerUntil=0;persist();render();toast('Sleep timer ended. Rest well.')},min*60000)}closeModal();render();toast(min?'Timer set for '+min+' minutes.':'Sleep timer off.')}break;case'bookmark':if(a){if(!a.bookmarks.includes(a.position||0))a.bookmarks.push(a.position||0);persist();toast('Passage bookmarked.');render()}break;case'bookmarks':if(a)modal('Words to come back to.',`<div class="bookmark-list">${a.bookmarks.map(i=>btn('<small>Passage '+(i+1)+'</small><p>'+esc(sentences(a.text)[i]||'')+'</p>','bookmark-jump','bookmark-item',`data-index="${i}"`)).join('')}</div>`);break;case'bookmark-jump':closeModal();seekTo(Number(b.dataset.index));break;case'actions':{const target=state.articles.find(a=>a.id===b.dataset.id);if(!target)break;modal('A little more.',`<div class="modal-article">${art(target.theme)}<strong>${esc(target.title)}</strong></div>${btn(icon('queue')+' Add to listening queue','enqueue','option-row',`data-id="${target.id}"`)}${btn(icon('check')+' '+(target.finished?'Mark as unread':'Mark as finished'),'finished','option-row',`data-id="${target.id}"`)}${btn(icon('file')+' Download article text','download','option-row',`data-id="${target.id}"`)}${target.url?`<a class="option-row" href="${esc(target.url)}" target="_blank" rel="noopener noreferrer">${icon('link')} Open original</a>`:''}${btn(icon('trash')+' Remove from library','delete-confirm','option-row danger',`data-id="${target.id}"`)}`);break}case'enqueue':if(b.dataset.id===state.currentId)toast('This article is already in the player.');else if(state.queue.includes(b.dataset.id))toast('Already in your queue.');else{state.queue.push(b.dataset.id);persist();toast('Added to your listening queue.')}closeModal();if(view==='queue')render();break;case'dequeue':state.queue=state.queue.filter(x=>x!==b.dataset.id);persist();render();break;case'move-up':{const i=state.queue.indexOf(b.dataset.id);if(i>0)[state.queue[i-1],state.queue[i]]=[state.queue[i],state.queue[i-1]];persist();render();break}case'finished':{const t=state.articles.find(a=>a.id===b.dataset.id);t.finished=!t.finished;persist();closeModal();render();break}case'delete-confirm':modal('Remove this article?',`<p class="modal-intro">This removes the article and its bookmarks from this browser. Export a backup first if you want to keep it.</p>${btn('Remove article','delete','button danger-button',`data-id="${b.dataset.id}"`)}${btn('Keep it','close-modal','secondary-button')}`);break;case'delete':if(b.dataset.id===state.currentId){stopSpeech();state.currentId=null}state.articles=state.articles.filter(x=>x.id!==b.dataset.id);state.queue=state.queue.filter(x=>x!==b.dataset.id);persist();closeModal();if(view==='player')view='library';render();toast('Article removed.');break;case'download':{const t=state.articles.find(a=>a.id===b.dataset.id);download(t.title+'\n\n'+t.text,t.title+'.txt','text/plain');closeModal();break}case'export':download(JSON.stringify(state,null,2),'sona-library.json','application/json');toast('Backup downloaded.');break;case'close-modal':closeModal();break}}
function seekTo(i){const a=current();if(!a)return;a.position=clamp(i,0,sentences(a.text).length-1);a.finished=false;persist();if(playing)speakFrom(a.position);else updatePlayback()}
function download(data,name,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name.replace(/[\\/:*?"<>|]/g,'-');a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
async function importForm(e){e.preventDefault();if(busy)return;const url=$('#article-url')?.value,title=$('#article-title')?.value,text=$('#article-text')?.value,file=$('#article-file')?.files[0];busy=true;preview=null;const button=$('#import-form button[type="submit"]');button.disabled=true;button.innerHTML='<span class="spinner"></span> Preparing your reading…';$('#import-error').textContent='';try{let data;if(importMode==='url'){const r=await fetch('/api/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url})});data=await r.json();if(!r.ok)throw new Error(data.error||'Could not load article.')}else if(importMode==='text'){if(!text?.trim())throw new Error('Add some text first.');data={title:title.trim(),text:text.trim(),source:'Your words',author:''}}else{if(!file)throw new Error('Choose a file first.');if(file.size>15*1024*1024)throw new Error('Please choose a file smaller than 15 MB.');let words;if(/\.pdf$/i.test(file.name)){const pdfjs=await import('https://cdn.jsdelivr.net/npm/pdfjs-dist@5.4.394/build/pdf.mjs');pdfjs.GlobalWorkerOptions.workerSrc='https://cdn.jsdelivr.net/npm/pdfjs-dist@5.4.394/build/pdf.worker.mjs';const pdf=await pdfjs.getDocument({data:await file.arrayBuffer()}).promise;const pages=[];for(let i=1;i<=pdf.numPages;i++){const page=await pdf.getPage(i);const content=await page.getTextContent();pages.push(content.items.map(x=>x.str).join(' '))}words=pages.join('\n\n');if(words.trim().length<30)throw new Error('This PDF may be a scanned image. Copy its text with OCR and use Paste text.')}else if(/\.html?$/i.test(file.name)){const doc=new DOMParser().parseFromString(await file.text(),'text/html');doc.querySelectorAll('script,style,nav,footer,header').forEach(n=>n.remove());words=(doc.querySelector('article,main')||doc.body).textContent}else words=await file.text();data={title:file.name.replace(/\.[^.]+$/,''),text:words.trim(),source:'Your files',author:''}}if(!validArticle(data))throw new Error('No readable text was found.');if(data.text.length>150000)throw new Error('This article is too long. Please split it into smaller sections.');preview={...data,theme:classify(data.title+' '+data.text)};busy=false;render();$('.preview-card')?.scrollIntoView({behavior:'smooth',block:'center'})}catch(err){busy=false;button.disabled=false;button.innerHTML=importMode==='url'?'Find article':'Prepare article';$('#import-error').textContent=err.message}}
function bind(){$('#app').onclick=e=>{const b=e.target.closest('[data-action]');if(b)action(b.dataset.action,b)};$('#voice-search')?.addEventListener('input',e=>{voiceQuery=e.target.value;const pos=e.target.selectionStart;render();$('#voice-search')?.focus();$('#voice-search')?.setSelectionRange(pos,pos)});$('#search')?.addEventListener('input',e=>{query=e.target.value;const position=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(position,position)});$('#seek')?.addEventListener('change',e=>seekTo(Number(e.target.value)));$('#import-form')?.addEventListener('submit',importForm);$('#autoplay')?.addEventListener('change',e=>{state.autoplay=e.target.checked;persist()});$('#backup-file')?.addEventListener('change',async e=>{try{const f=e.target.files[0];if(!f||f.size>15000000)throw new Error('Choose a Sona backup smaller than 15 MB.');const data=JSON.parse(await f.text());if(!Array.isArray(data.articles)||!data.articles.every(validArticle))throw new Error('This is not a valid Sona backup.');const existing=new Set(state.articles.map(a=>a.id));for(const a of data.articles)if(!existing.has(a.id)){const id=crypto.randomUUID();state.articles.push({...a,id,theme:classify(a.title+' '+a.text),bookmarks:Array.isArray(a.bookmarks)?a.bookmarks.filter(Number.isInteger):[],position:Math.max(0,Number(a.position)||0)})}persist();render();toast('Backup imported. Your existing articles were kept.')}catch(e){toast(e.message)}})}
function loadVoices(){voices=window.speechSynthesis?.getVoices()||[];voices.sort((a,b)=>a.lang.localeCompare(b.lang)||a.name.localeCompare(b.name));if(!state.voiceURI&&voices.length){const v=voices.find(v=>v.default)||voices.find(v=>v.lang.startsWith('en'))||voices[0];state.voiceURI=v.voiceURI;persist()}if($('#modal-root').textContent.includes('Find your voice.'))voiceModal();else if(view==='player'&&!playing)render()}
if('speechSynthesis'in window){window.speechSynthesis.addEventListener('voiceschanged',loadVoices);loadVoices();setTimeout(loadVoices,1000)}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.code==='Space'&&!['INPUT','TEXTAREA','BUTTON','SELECT'].includes(document.activeElement?.tagName)&&!$('#modal-root').children.length){e.preventDefault();toggle()}});window.addEventListener('beforeunload',()=>{persist();window.speechSynthesis?.cancel()});window.addEventListener('online',()=>flushCloud(true));window.addEventListener('focus',()=>{if(cloudReady&&!playing)flushCloud(true)});if('mediaSession'in navigator){try{navigator.mediaSession.setActionHandler('play',()=>speakFrom(current()?.position||0));navigator.mediaSession.setActionHandler('pause',()=>{stopSpeech();render()})}catch{}}render();initCloud();loadProvider();

function setCloudStatus(label){cloudStatus=label;document.querySelectorAll('.cloud-status').forEach(n=>n.textContent=label);sonaController.publish(publicSnapshot())}
function stampChanges(){const now=Date.now();for(const a of state.articles){const old=fingerprints.get(a.id);const compare=JSON.stringify(a);if(compare!==old){a.updatedAt=now;fingerprints.set(a.id,JSON.stringify(a))}}for(const id of fingerprints.keys()){if(!state.articles.some(a=>a.id===id)){state.deleted[id]=now;fingerprints.delete(id)}}state.updatedAt=now;}
async function cloudRequest(method='GET',body){const res=await fetch('/api/cloud/library',{method,headers:body?{'Content-Type':'application/json'}:{},...(body?{body:JSON.stringify(body)}:{})});const data=await res.json();if(!res.ok&&res.status!==409)throw new Error(data.error||'Cloud sync unavailable.');return {res,data}}
function rememberState(){try{localStorage.setItem('sona.v1',JSON.stringify(state))}catch{}for(const a of state.articles)fingerprints.set(a.id,JSON.stringify(a))}
async function initCloud(){try{const {data}=await cloudRequest();cloudRevision=data.revision;if(data.state){const engine=state.audioEngine;state=hasLocal?mergeStates(state,data.state):{...state,...data.state};state.audioEngine=engine;rememberState()}cloudReady=true;setCloudStatus('Cloud connected');render();await flushCloud()}catch(e){setCloudStatus(navigator.onLine===false?'Offline · saved on device':'Cloud unavailable · saved on device');render()}}
async function flushCloud(refresh=false){if(!cloudReady){if(refresh)await initCloud();return false}if(cloudSaving)return false;cloudSaving=true;try{setCloudStatus('Syncing…');if(refresh){const {data}=await cloudRequest();if(data.state){const engine=state.audioEngine;state=mergeStates(state,data.state);state.audioEngine=engine;cloudRevision=data.revision;rememberState()}}let attempts=0;while(attempts++<3){const snapshot=JSON.stringify(state);const {res,data}=await cloudRequest('PUT',{state,revision:cloudRevision});cloudRevision=data.revision;if(res.status===409){const engine=state.audioEngine;state=mergeStates(state,data.state||{});state.audioEngine=engine;rememberState();continue}cloudDirty=JSON.stringify(state)!==snapshot;setCloudStatus('Cloud saved');cloudSaving=false;if(cloudDirty){clearTimeout(syncTimer);syncTimer=setTimeout(()=>flushCloud(),700)}else if(refresh&&!playing)render();return true}throw new Error('Another device is updating this library. Try syncing again.')}catch(e){setCloudStatus('Saved on device · sync pending');cloudDirty=true;return false}finally{cloudSaving=false}}
async function loadProvider(){try{const [er,tr]=await Promise.all([fetch('/api/eleven/status'),fetch('/api/tts/status')]);const [e,t]=await Promise.all([er.json(),tr.json()]);providerInfo={...t,connected:e.connected};if(e.connected)await loadPremiumVoices();for(const provider of ['google','azure'])if(providerInfo[provider])await loadFreeVoices(provider);if(!e.connected&&providerInfo.google&&state.audioEngine==='eleven'){state.audioEngine='google';persist()}if(!playing)render()}catch{}}
async function loadPremiumVoices(){const r=await fetch('/api/eleven/voices');const d=await r.json();if(!r.ok)throw new Error(d.error||'Could not load ElevenLabs voices.');premiumVoices=d.voices||[];premiumModels=d.models||[];if(!premiumVoices.some(v=>v.id===state.elevenVoice))state.elevenVoice=premiumVoices[0]?.id||'';if(!premiumModels.some(m=>m.id===state.elevenModel)){state.elevenModel=['eleven_v4_turbo','eleven_v3_conversational','eleven_flash_v2_5','eleven_multilingual_v2'].find(id=>premiumModels.some(m=>m.id===id))||'eleven_multilingual_v2'}return d}
async function loadFreeVoices(provider){const r=await fetch('/api/tts/voices?provider='+provider),d=await r.json();if(!r.ok)throw new Error(d.error||'Could not load voices.');freeVoices[provider]=d.voices||[];const key=provider+'Voice';if(!freeVoices[provider].some(v=>v.id===state[key]))state[key]=freeVoices[provider].find(v=>v.id==='en-US-Chirp3-HD-Aoede')?.id||freeVoices[provider][0]?.id||'';return freeVoices[provider]}
async function selectProvider(provider){state.audioEngine=provider;persist();if(provider==='device'){view='voices';render();return}if(provider==='eleven'){if(!providerInfo.connected){connectModal();return}try{await loadPremiumVoices();view='voices';render()}catch(e){toast(e.message)}return}try{const r=await fetch('/api/tts/status'),d=await r.json();if(r.ok)providerInfo={...providerInfo,...d}}catch{}if(!providerInfo[provider]){view='voices';render();toast(provider==='google'?'Google Chirp is not ready in Lire. Open Lire and check its Google voice connection.':'Connect Azure Neural to choose its voices.');return}try{await loadFreeVoices(provider);view='voices';render()}catch(e){toast(e.message)}}
function providerPicker(){modal('Choose a voice',`<p class="modal-intro">High quality narration, with generous free monthly allowances.</p><div class="provider-cards">${[['google','Google Chirp 3 HD','Existing Lire connection · 50,000 character monthly cap','Already configured in Lire; no second key needed.'],['azure','Azure Neural','500,000 characters free each month','Free F0 tier; limited to one concurrent request.'],['eleven','ElevenLabs','10,000 free credits each month','About 10 minutes; voice access varies by account.']].map(([id,title,quota,note])=>`<button class="provider-card" data-action="select-provider" data-provider="${id}"><strong>${title}</strong><span>${quota}</span><small>${note}</small><i>${providerInfo[id==='eleven'?'connected':id]?'Connected':'Set up'}</i></button>`).join('')}</div>${btn('Use device voices','use-device','text-button')}<p class="field-help">Provider quotas can change. Sona keeps keys in your private cloud storage and caches generated audio.</p>`)}
function freeConnectModal(provider){const google=provider==='google',title=google?'Google Chirp 3 HD':'Azure Neural',formId='free-tts-connect',fields=google?`<label class="field-label" for="tts-key">GOOGLE CLOUD API KEY</label><input id="tts-key" type="password" class="input" autocomplete="off" placeholder="Google Cloud API key" required minlength="15">`:`<label class="field-label" for="tts-key">AZURE SPEECH KEY</label><input id="tts-key" type="password" class="input" autocomplete="off" placeholder="Speech resource key" required minlength="15"><label class="field-label" for="tts-region">RESOURCE REGION</label><input id="tts-region" class="input" placeholder="e.g. canadacentral" required>`;modal('Connect '+title,`<p class="modal-intro">${google?'Google’s Chirp 3 HD is its expressive, high-quality voice family.':'Azure Neural voices sound natural and support many languages.'} Set up your provider account, then connect a key.</p><form id="${formId}">${fields}<p class="field-help">For Azure, Sona sends the key to Lire over HTTPS. Lire stores it in private server-side storage and shares the connection with Sona. The key is never saved in browser storage or this chat.</p><button type="submit" class="button">Connect ${title}</button><p class="error" id="tts-error" role="alert"></p></form><div class="quota-note"><strong>Free allowance</strong><p>${google?'Sona reuses Lire’s Google Cloud connection and its shared 50,000-character monthly cap. No second key is needed.':'Azure F0 includes up to 500,000 Neural characters per month. Check that the Speech resource is F0; S0 usage can be billed.'}</p></div>${btn('Back to voice choices','voices','text-button')}`);$('#'+formId).onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button'),input=$('#tts-key');button.disabled=true;button.textContent='Checking key…';let key=input.value;try{const body={provider,key};if(!google)body.region=$('#tts-region').value;const r=await fetch('/api/tts/connect',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});key='';input.value='';const d=await r.json();if(!r.ok)throw new Error(d.error);providerInfo[provider]=true;if(provider==='azure')providerInfo.azureViaLire=true;await loadFreeVoices(provider);state.audioEngine=provider;persist();closeModal();view='voices';render();toast(title+' connected.')}catch(err){key='';input.value='';$('#tts-error').textContent=err.message;button.disabled=false;button.textContent='Connect '+title}}}
function freeVoiceModal(provider){const list=freeVoices[provider]||[],selected=state[provider+'Voice'];modal('Find your voice.',`<p class="modal-intro">${provider==='google'?'Google Chirp 3 HD':'Azure Neural'} · high fidelity text to speech<br>Generated audio is cached in your private cloud library.</p><div class="voice-list">${list.map((v,i)=>`<button class="voice-option ${v.id===selected?'chosen':''}" data-action="choose-free-voice" data-provider="${provider}" data-voice="${esc(v.id)}"><span class="orb orb-${i%3}"></span><span><strong>${esc(v.name)}</strong><small>${esc(v.language||'Neural voice')}</small></span>${v.id===selected?icon('check'):icon('headphones')}</button>`).join('')}</div><p class="field-help">${provider==='google'?'Lire connection · global 800,000-character monthly cap across Lire and Sona.':'500,000 characters free per month on Azure F0.'} Replays use cached audio.</p>${btn('Change voice provider','voices','text-button')} ${btn('Disconnect '+(provider==='google'?'Google':'Azure'),'disconnect-free','text-button',`data-provider="${provider}"`)}`)}
function elevenVoiceModal(){modal('Find your voice.',`<p class="modal-intro">ElevenLabs streaming · ${esc(premiumModels.find(m=>m.id===state.elevenModel)?.name||'Natural speech')}<br>Generated audio is cached in your private cloud library.</p><div class="voice-list">${premiumVoices.map((v,i)=>`<button class="voice-option ${v.id===state.elevenVoice?'chosen':''}" data-action="choose-premium" data-voice="${esc(v.id)}"><span class="orb orb-${i%3}"></span><span><strong>${esc(v.name)}</strong><small>${esc([v.labels?.accent,v.labels?.gender,v.labels?.description].filter(Boolean).join(' · ')||v.description?.slice(0,100)||'ElevenLabs voice')}</small></span>${v.id===state.elevenVoice?icon('check'):icon('headphones')}</button>`).join('')}</div><p class="field-help">Free plan: 10,000 credits/month, roughly 10 minutes. Replays use cached audio.</p>${btn('Change voice provider','voices','text-button')} ${btn('Disconnect ElevenLabs','disconnect-eleven','text-button')}`)}
function connectModal(){modal('Connect ElevenLabs',`<p class="modal-intro">ElevenLabs has a limited free tier. Choose a free monthly plan or a paid account, then connect a restricted API key.</p><form id="eleven-connect"><label class="field-label" for="eleven-key">ELEVENLABS API KEY</label><input id="eleven-key" type="password" class="input" autocomplete="off" placeholder="Your restricted API key" required minlength="15"><p class="field-help">Needs Voices read, Models read, and Text to Speech permissions. Stored only in your private server-side storage; never returned to this page.</p><button type="submit" class="button">Connect ElevenLabs</button><p class="error" id="eleven-error" role="alert"></p></form><p class="field-help">Free plan: 10,000 credits/month, roughly 10 minutes. Replays use cached audio. API voice access may vary.</p>${btn('Back to voice choices','voices','text-button')}`);$('#eleven-connect').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;button.textContent='Connecting…';const input=$('#eleven-key');let key=input.value;try{const r=await fetch('/api/eleven/connect',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key})});key='';input.value='';const d=await r.json();if(!r.ok)throw new Error(d.error);providerInfo.connected=true;state.audioEngine='eleven';await loadPremiumVoices();persist();closeModal();voiceModal()}catch(err){key='';input.value='';$('#eleven-error').textContent=err.message;button.disabled=false;button.textContent='Connect ElevenLabs'}}}
function voiceModal(){closeModal();view='voices';render();window.scrollTo(0,0)}
async function disconnectEleven(){stopSpeech();try{const r=await fetch('/api/eleven/connect',{method:'DELETE'});if(!r.ok)throw new Error();providerInfo.connected=false;premiumVoices=[];state.audioEngine='google';persist();closeModal();render();toast('ElevenLabs disconnected.')}catch{toast('Could not disconnect. Please try again.')}}
async function speakPremium(index){const engine=state.audioEngine;if(!audio){toast('Audio playback is unavailable in this browser.');return}stopSpeech();const a=current();if(!a)return;const ss=sentences(a.text);a.position=clamp(index,0,ss.length-1);a.finished=false;playing=true;audioLoading=true;const token=speechToken;persist();render();const startId=a.id;const abort=new AbortController();audioAbort=abort;try{if(engine==='eleven'&&!premiumVoices.length)await loadPremiumVoices();if(['google','azure'].includes(engine)&&!freeVoices[engine].length)await loadFreeVoices(engine);for(let wait=0;cloudSaving&&wait<50;wait++)await new Promise(resolve=>setTimeout(resolve,100));const synced=await flushCloud();if(!synced&&cloudDirty)throw new Error('Wait for Cloud saved before starting premium narration.');const response=await fetch(engine==='eleven'?'/api/eleven/prepare':'/api/tts/prepare',{method:'POST',signal:abort.signal,headers:{'Content-Type':'application/json'},body:JSON.stringify(engine==='eleven'?{articleId:startId,start:a.position,voice:state.elevenVoice,model:state.elevenModel}:{articleId:startId,start:a.position,voice:state[engine+'Voice'],provider:engine})});const segment=await response.json();if(!response.ok)throw new Error(segment.error||'Could not prepare narration.');if(token!==speechToken)return;audio.src=segment.url;audio.preload='auto';audio.playbackRate=state.rate;audio.onplaying=()=>{if(token!==speechToken)return;audioLoading=false;setMedia(a);};audio.ontimeupdate=()=>{if(token!==speechToken)return;const parts=ss.slice(segment.start,segment.end);const seconds=Number.isFinite(audio.duration)&&audio.duration>0?audio.duration:parts.join(' ').split(/\s+/).length/155*60;const total=parts.reduce((n,s)=>n+s.length,0),target=audio.currentTime/seconds*total;let offset=0,idx=segment.start;for(const part of parts){offset+=part.length;if(offset>=target)break;idx++}const active=current();if(active&&active.id===startId&&active.position!==idx){active.position=clamp(idx,segment.start,segment.end-1);persist();updatePlayback()}};audio.onended=()=>{if(token!==speechToken)return;const active=current();if(!active)return;active.position=segment.end;persist();if(segment.end>=segment.total)finishArticle();else speakPremium(segment.end)};audio.onerror=async()=>{if(token!==speechToken)return;let message='Narration could not load. Check your provider key, free-tier quota and voice settings, then try again.';if(engine==='google'){message='Google narration could not load. Choose another voice or try again later.';try{const failure=await fetch(segment.url,{signal:abort.signal});if(!failure.ok){const detail=await failure.json();if(detail.error)message=detail.error}else await failure.body?.cancel()}catch{}}if(token!==speechToken)return;stopSpeech();render();toast(message)};await audio.play();}catch(e){if(e.name==='AbortError'||token!==speechToken)return;stopSpeech();render();toast(e.name==='NotAllowedError'?'Your browser needs another tap to start audio. Press play again.':e.message)}}
function setMedia(a){if(!('mediaSession'in navigator)||typeof MediaMetadata==='undefined')return;navigator.mediaSession.metadata=new MediaMetadata({title:a.title,artist:a.author||a.source,album:'Sona '+SONA_VERSION+' / Stillwater',artwork:[{src:location.origin+'/art/'+a.theme+'.svg',type:'image/svg+xml'}]});navigator.mediaSession.playbackState=playing?'playing':'paused'}
